// The brand's boot sequence (brand src/motion.ts), driven frame-exactly by t instead of CSS animations.
// It reads assets/boot.svg (generated by the brand code) and reproduces its keyframes:
//   .pl  plates: 0.5 s, cubic-bezier(.2,.7,.2,1), from opacity 0 + translate(--x,--y) to rest, delay --d
//   .sig signal mark: 0.5 s ease-out from 1.35 s
//   .sw  glint sweep: 0.75 s cubic-bezier(.4,0,.6,1) from 1.2 s; opacity 0 -> .85 (12%) -> .85 (88%) -> 0; translateY 0 -> 697.23
//   .ch  letters: 0.06 s linear, delay --d
// Total 3.6 s (BOOT_SECONDS). boot(t) with t in seconds from the start of the boot.
(() => {
  const { bezier, EASE, clamp, css, op } = window.FILM;
  const EASE_OUT = bezier(0, 0, 0.58, 1);           // CSS "ease-out"
  const SW = bezier(0.4, 0, 0.6, 1);
  async function boot(container, { width, src = 'assets/boot.svg' } = {}) {
    const markup = window.FILM.assetText?.[src];
    if (!markup) throw new Error('boot.svg not loaded');
    container.innerHTML = markup.replace(/<style>[\s\S]*?<\/style>/, '');
    const svg = container.querySelector('svg');
    svg.removeAttribute('width'); svg.removeAttribute('height');
    svg.style.width = width + 'px'; svg.style.height = 'auto'; svg.style.display = 'block'; svg.style.overflow = 'visible';
    const num = (el, v) => parseFloat(el.style.getPropertyValue(v));
    const plates = [...svg.querySelectorAll('.pl')].map((el) => ({ el, d: num(el, '--d'), x: num(el, '--x'), y: num(el, '--y') }));
    const letters = [...svg.querySelectorAll('.ch')].map((el) => ({ el, d: num(el, '--d') }));
    const sig = svg.querySelector('.sig'), sw = svg.querySelector('.sw');
    letters.forEach(({ el }) => el.setAttribute('fill', '#8E58D2'));
    const vb = svg.viewBox.baseVal;
    return {
      el: svg, viewBox: { x: vb.x, y: vb.y, w: vb.width, h: vb.height },
      letterTimes: letters.map((l) => l.d), plateTimes: plates.map((p) => p.d),
      render(t) {
        for (const p of plates) {
          const k = EASE(clamp((t - p.d) / 0.5));
          css(p.el, { opacity: op(k), transform: k >= 1 ? 'none' : `translate(${(p.x * (1 - k)).toFixed(3)}px, ${(p.y * (1 - k)).toFixed(3)}px)` });
        }
        css(sig, { opacity: op(EASE_OUT(clamp((t - 1.35) / 0.5))) });
        const u = clamp((t - 1.2) / 0.75);
        let o;
        if (t < 1.2 || u >= 1) o = 0;
        else if (u < 0.12) o = 0.85 * SW(u / 0.12);
        else if (u < 0.88) o = 0.85;
        else o = 0.85 * (1 - SW((u - 0.88) / 0.12));
        css(sw, { opacity: op(o), transform: `translateY(${(697.23 * SW(u)).toFixed(3)}px)` });
        for (const l of letters) css(l.el, { opacity: op((t - l.d) / 0.06) });
      },
    };
  }
  window.FILM.boot = boot;
})();
